void ClimateViewBase::flexButtonCallbackHandler(const touchgfx::AbstractButtonContainer& src)
{
    if (&src == &back_flex)
    {
        //back_2
        //When back_flex clicked change screen to Main
        //Go to Main with screen transition towards West
        application().gotoMainScreenSlideTransitionWest();
    }
}

void ClimateViewBase::buttonCallbackHandler(const touchgfx::AbstractButton& src)
{
    if (&src == &plus_climate)
    {
        //onPlusClimateClicked
        //When plus_climate clicked call virtual function
        //Call onPlusClimateClicked
        onPlusClimateClicked();
    }
    if (&src == &minus_climate)
    {
        //onMinusClimateClicked
        //When minus_climate clicked call virtual function
        //Call onMinusClimateClicked
        onMinusClimateClicked();
    }
    if (&src == &fan_toggle)
    {
        //onFanToggleClicked
        //When fan_toggle clicked call virtual function
        //Call onFanToggleClicked
        onFanToggleClicked();
    }
    if (&src == &auto_mode)
    {
        //onAutoModeClicked
        //When auto_mode clicked call virtual function
        //Call onAutoModeClicked
        onAutoModeClicked();
    }
}
